yakit.AutoInitYakit()

# Input your code!

image_data = cli.Text("image", cli.setRequired(true),cli.setHelp("base64图片，或者url"))
image_type = cli.StringSlice("type", cli.setRequired(true),cli.setSelectOption("base64", "base64"),cli.setSelectOption("url", "url"),cli.setDefault("base64"),cli.setSelectOption("base64-gzip", "base64-gzip"))
cli.check()
base64_url = "data:image/png;base64,%v"
mark_image = "![图片](%v)"


if image_type[0] == "url"{
    yakit.Markdown(str.f(mark_image,image_data))
}else if image_type[0] == "base64"{
    image_url = str.f(base64_url,image_data)
    yakit.Markdown(str.f(mark_image,image_url))
}else if image_type[0] == "base64-gzip"{
    data, err = codec.DecodeBase64(image_data)
    if err != nil{
        yakit.Error("base64解码错误!")
        os.Exit(0)
    }
    if gzip.IsGzip(data){
        data = gzip.Decompress(data)~
        image_url = str.f(base64_url,codec.EncodeBase64(data))
        yakit.Markdown(str.f(mark_image,image_url))
    }else{
        yakit.Error("未识别到gzip格式！")
        os.Exit(0)
    }
}
